16: package org.springframework.samples.petclinic.api.boundary.web;
17: 
18: import org.springframework.cloud.client.circuitbreaker.ReactiveCircuitBreaker;
19: import org.springframework.cloud.client.circuitbreaker.ReactiveCircuitBreakerFactory;
20: import org.springframework.samples.petclinic.api.application.CustomersServiceClient;
21: import org.springframework.samples.petclinic.api.application.VisitsServiceClient;
22: import org.springframework.samples.petclinic.api.dto.OwnerDetails;
23: import org.springframework.samples.petclinic.api.dto.Visits;
24: import org.springframework.web.bind.annotation.GetMapping;
25: import org.springframework.web.bind.annotation.PathVariable;
26: import org.springframework.web.bind.annotation.RequestMapping;
27: import org.springframework.web.bind.annotation.RestController;
28: import reactor.core.publisher.Mono;
29: 
30: import java.util.List;
31: import java.util.function.Function;
32: 
33: /**
34:  * @author Maciej Szarlinski
35:  */
36: @RestController
37: @RequestMapping("/api/gateway")
38: public class ApiGatewayController {
39: 
40:     private final CustomersServiceClient customersServiceClient;
41: 
42:     private final VisitsServiceClient visitsServiceClient;
43: 
44:     private final ReactiveCircuitBreakerFactory cbFactory;
45: 
46:     public ApiGatewayController(CustomersServiceClient customersServiceClient,
47:                                 VisitsServiceClient visitsServiceClient,
48:                                 ReactiveCircuitBreakerFactory cbFactory) {
49:         this.customersServiceClient = customersServiceClient;
50:         this.visitsServiceClient = visitsServiceClient;
51:         this.cbFactory = cbFactory;
52:     }
53: 
54:     @GetMapping(value = "owners/{ownerId}")
55:     public Mono<OwnerDetails> getOwnerDetails(final @PathVariable int ownerId) {
56:         return customersServiceClient.getOwner(ownerId)
57:             .flatMap(owner ->
58:                 visitsServiceClient.getVisitsForPets(owner.getPetIds())
59:                     .transform(it -> {
60:                         ReactiveCircuitBreaker cb = cbFactory.create("getOwnerDetails");
61:                         return cb.run(it, throwable -> emptyVisitsForPets());
62:                     })
63:                     .map(addVisitsToOwner(owner))
64:             );
65: 
66:     }
67: 
68:     private Function<Visits, OwnerDetails> addVisitsToOwner(OwnerDetails owner) {
69:         return visits -> {
70:             owner.pets()
71:                 .forEach(pet -> pet.visits()
72:                     .addAll(visits.items().stream()
73:                         .filter(v -> v.petId() == pet.id())
74:                         .toList())
75:                 );
76:             return owner;
77:         };
78:     }
79: 
80:     private Mono<Visits> emptyVisitsForPets() {
81:         return Mono.just(new Visits(List.of()));
82:     }
83: }

