41: /**
42:  * @author Maciej Szarlinski
43:  */
44: @EnableDiscoveryClient
45: @SpringBootApplication
46: public class ApiGatewayApplication {
47: 
48:     public static void main(String[] args) {
49:         SpringApplication.run(ApiGatewayApplication.class, args);
50:     }
51: 
52:     @Bean
53:     @LoadBalanced
54:     RestTemplate loadBalancedRestTemplate() {
55:         return new RestTemplate();
56:     }
57: 
58:     @Bean
59:     @LoadBalanced
60:     public WebClient.Builder loadBalancedWebClientBuilder() {
61:         return WebClient.builder();
62:     }
63: 
64:     @Bean
65:     RouterFunction<?> routerFunction() {
66:         Resource indexHtml = new ClassPathResource("static/index.html");
67:         var htmlNavigation = RequestPredicates.GET("/**")
68:             .and(RequestPredicates.headers(headers -> headers.accept().stream()
69:                 .anyMatch(mediaType -> mediaType.isCompatibleWith(MediaType.TEXT_HTML)
70:                     && !mediaType.isWildcardType()
71:                     && !mediaType.isWildcardSubtype())))
72:             .and(RequestPredicates.path("/api/**").negate())
73:             .and(RequestPredicates.path("/actuator/**").negate())
74:             .and(RequestPredicates.path("/webjars/**").negate())
75:             .and(RequestPredicates.path("/fallback").negate());
76: 
77:         return RouterFunctions.route(htmlNavigation,
78:             request -> ServerResponse.ok().contentType(MediaType.TEXT_HTML).bodyValue(indexHtml));
79:     }
80: 
81:     /**
82:      * Default Resilience4j circuit breaker configuration
83:      */
84:     @Bean
85:     public Customizer<ReactiveResilience4JCircuitBreakerFactory> defaultCustomizer() {
86:         return factory -> factory.configureDefault(id -> new Resilience4JConfigBuilder(id)
87:             .circuitBreakerConfig(CircuitBreakerConfig.ofDefaults())
88:             .timeLimiterConfig(TimeLimiterConfig.custom().timeoutDuration(Duration.ofSeconds(10)).build())
89:             .build());
90:     }
91: }

