68:     private Function<Visits, OwnerDetails> addVisitsToOwner(OwnerDetails owner) {
69:         return visits -> {
70:             owner.pets()
71:                 .forEach(pet -> pet.visits()
72:                     .addAll(visits.items().stream()
73:                         .filter(v -> v.petId() == pet.id())
74:                         .toList())
75:                 );
76:             return owner;
77:         };
78:     }
79: 
80:     private Mono<Visits> emptyVisitsForPets() {
81:         return Mono.just(new Visits(List.of()));
