39: 
40:     private static final Logger log = LoggerFactory.getLogger(PetResource.class);
41: 
42:     private final PetRepository petRepository;
43:     private final OwnerRepository ownerRepository;
44: 
45:     PetResource(PetRepository petRepository, OwnerRepository ownerRepository) {
46:         this.petRepository = petRepository;
47:         this.ownerRepository = ownerRepository;
48:     }
49: 
50:     @GetMapping("/petTypes")
51:     public List<PetType> getPetTypes() {
52:         return petRepository.findPetTypes();
53:     }
54: 
55:     @PostMapping("/owners/{ownerId}/pets")
56:     @ResponseStatus(HttpStatus.CREATED)
57:     public Pet processCreationForm(
58:         @RequestBody @Valid PetRequest petRequest,
59:         @PathVariable("ownerId") @Min(1) int ownerId) {
60: 
61:         Owner owner = ownerRepository.findById(ownerId)
62:             .orElseThrow(() -> new ResourceNotFoundException("Owner " + ownerId + " not found"));
63: 
64:         final Pet pet = new Pet();
65:         owner.addPet(pet);
66:         return save(pet, petRequest);
67:     }
68: 
69:     @PutMapping("/owners/*/pets/{petId}")
70:     @ResponseStatus(HttpStatus.NO_CONTENT)
71:     public void processUpdateForm(@Valid @RequestBody PetRequest petRequest,
72:                                   @PathVariable("petId") @Min(1) int petId) {
73:         Pet pet = findPetById(petId);
74:         save(pet, petRequest);
75:     }
76: 
77:     private Pet save(final Pet pet, final PetRequest petRequest) {
78: 
79:         pet.setName(petRequest.name());
80:         pet.setBirthDate(petRequest.birthDate());
81: 
82:         petRepository.findPetTypeById(petRequest.typeId())
83:             .ifPresent(pet::setType);
84: 
85:         log.info("Saving pet {}", pet);
86:         return petRepository.save(pet);
87:     }
88: 
89:     @GetMapping("owners/*/pets/{petId}")
90:     public PetDetails findPet(@PathVariable("petId") int petId) {
91:         Pet pet = findPetById(petId);
92:         return new PetDetails(pet);
93:     }
94: 
95: 
96:     private Pet findPetById(int petId) {
97:         return petRepository.findById(petId)
98:             .orElseThrow(() -> new ResourceNotFoundException("Pet " + petId + " not found"));
99:     }
100: 
101: }

