3: export function useRequest(load) {
4:     const loading = ref(true);
5:     const failed = ref(false);
6:     const failure = ref(null);
7:     let controller = null;
8:     let unmounted = false;
9: 
10:     async function run() {
11:         controller?.abort();
12:         const currentController = new AbortController();
13:         controller = currentController;
14:         loading.value = true;
15:         failed.value = false;
16:         failure.value = null;
17: 
18:         try {
19:             await load({ signal: currentController.signal });
20:         } catch (error) {
21:             if (!currentController.signal.aborted) {
22:                 failed.value = true;
23:                 failure.value = error;
24:             }
25:         } finally {
26:             if (controller === currentController) {
27:                 controller = null;
28:                 if (!unmounted) {
29:                     loading.value = false;
30:                 }
31:             }
32:         }
33:     }
34: 
35:     onMounted(run);
36:     onUnmounted(() => {
37:         unmounted = true;
38:         controller?.abort();
39:     });
40:     return {
41:         loading,
42:         failed,
43:         failure
44:     };
45: }

